use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_Input: i32,
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_Input(container.api_Input);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(Input: i32)
{
  put_Input(Input);
}

/// setter for IN DataPort
pub fn put_Input(value: i32)
{
  *extern_api::IN_Input.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// getter for OUT DataPort
pub fn get_Output() -> i32
{
  return extern_api::OUT_Output.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}
